package com.collectiq.web;
import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.client.RestClient;import java.util.*;
@RestController @RequestMapping("/api/whatsapp") public class WhatsAppController{
 private final JdbcTemplate db;private final RestClient http=RestClient.create();@Value("${WHATSAPP_TOKEN:}")String token;@Value("${WHATSAPP_PHONE_NUMBER_ID:}")String phoneId;@Value("${WHATSAPP_API_VERSION:v21.0}")String version;
 public WhatsAppController(JdbcTemplate d){db=d;}
 @GetMapping("/status")public Map<String,Object> status(){return Map.of("configured",!token.isBlank()&&!phoneId.isBlank(),"mode","Cloud API; outbound sends require approval");}
 @PostMapping("/send-approved")public Map<String,Object> send(@RequestBody Map<String,String>b){if(token.isBlank()||phoneId.isBlank())throw new IllegalStateException("WhatsApp Cloud API credentials not configured");if(!Boolean.parseBoolean(b.getOrDefault("approved","false")))throw new IllegalArgumentException("Human approval required");String to=b.get("to"),message=b.get("message");if(to==null||message==null||message.length()>4000)throw new IllegalArgumentException("Valid recipient/message required");Map<String,Object> payload=Map.of("messaging_product","whatsapp","recipient_type","individual","to",to,"type","text","text",Map.of("preview_url",false,"body",message));Map response=http.post().uri("https://graph.facebook.com/"+version+"/"+phoneId+"/messages").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).body(payload).retrieve().body(Map.class);db.update("insert into audit_events(tenant_id,event_type,detail) values('demo','WHATSAPP_SENT',?::jsonb)",org.springframework.util.SerializationUtils.serialize(response)==null?"{}":"{}");return Map.of("sent",true,"providerResponse",response);}
}